<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useUserStore} from '../stores/user';const form=reactive({username:'admin',password:'password'}),loading=ref(false),router=useRouter(),route=useRoute(),user=useUserStore();async function submit(){loading.value=true;try{await user.login(form.username,form.password);router.push(String(route.query.redirect||'/dashboard'))}finally{loading.value=false}}</script>
<template><div class="login"><section class="login-intro"><div class="brand large"><span>智</span><div>智能OA<small>SMART OFFICE</small></div></div><h1>让协作更简单，<br/>让管理更智能。</h1><p>统一审批 · 高效协作 · 数据驱动</p></section><el-card class="login-card" shadow="always"><h2>欢迎登录</h2><p>请输入您的账号信息</p><el-form :model="form" label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="form.username" size="large" placeholder="请输入用户名"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password size="large" placeholder="请输入密码"/></el-form-item><el-button type="primary" size="large" native-type="submit" :loading="loading">登 录</el-button></el-form><el-divider>演示账号</el-divider><small>admin / password（也可使用 employee、manager、project）</small></el-card></div></template>
